// We model `nat` (non-negative integers) as `u64`.
pub type Nat = u64;

/// Returns the smallest element of `s` if it exists.
/// - If `s` is empty: returns `None`.
/// - Otherwise: returns `Some(v)` where `v` is an element of `s` and `v <= x` for all `x` in `s`.
pub fn find_smallest(s: &Vec<Nat>) -> Option<Nat> {
    if s.is_empty() {
        return None;
    }

    // Initialize with the first element; since the array is non-empty, this is safe.
    let mut min_val = s[0];
    for &x in s.iter().skip(1) {
        if x < min_val {
            min_val = x;
        }
    }
    Some(min_val)
}

